mapper.select:
SELECT p.product_name AS productName, p.product_code AS productCode, COUNT(d.device_code) AS deviceCount, ROUND( COUNT(d.device_code) * 100.0 / (SELECT COUNT(*) FROM wms_iot_device WHERE d.warehouse_code IN
#{warehouseCode}
), 2 ) AS ratio FROM wms_iot_product p LEFT JOIN wms_iot_device d ON p.product_code = d.product_code WHERE d.warehouse_code IN
#{warehouseCode}
GROUP BY p.product_code, p.product_name ORDER BY deviceCount desc
